with c(odu_id,libro,antes,despues) as (values
('odu-049','oraculo-sagrado',$q$[{"ref": "49.1", "yoruba": "Kosi abiyamo ti ko le bi awo lọmọ\nKosi abiyamo ti ko le bi Ọ̀rúnmìlà\nBaba-ẹni biobabini nipipe,\nbopẹtiti a tun nbi Baba-ẹni lomo,\nYeye-ẹni biobabini nipipe,\nbobapẹtiti a tun nbi yeye-ẹni l'ọmo:\na dífá f'Ọ̀rúnmìlà ti o wipe òun maa\nm'ọ̀run bọsayé òun maa mu\nayé l'osğrun.\nKiobaa leṣe bẹẹ dandan,\nWọ̀n niki ó rú\nOhun gbogbo ni méjiméji,\nako ati abo kan bayi:\nAgbo kan, àgutăn kan,\nòbúkọ kan, ewúrẹ kan,\nakuko-adiyẹ kan\nati agbebo-adiyẹ kan\nati bẹẹbẹẹ.\nÓ gbó ó rúbọ.\nBẹẹ ni ayé nbisii ti wọ̀n si nrẹ sii.\n\"No hay madre con hijos que no pueda haber parido\na un sacerdote de Ifá\"\n\"No hay madre con hijos, que no pueda haber parido a Ọ̀rúnmìlà\",\n\"Nuestro padre, si nos ha dado plena existencia,\ninevitablemente le daremos a él vida a cambio también\"\n\"Nuestra madre, si nos da plena existencia,\ninevitablemente le daremos a ella vida a cambio también.", "medicina": "", "comentario": "", "traduccion": "adivinaron Ifá para Ọ̀rúnmìlà,\ns* Significa que alguien puede dar vida, engendrar a quienes fueros sus ancestros.\nquien dijo que él bajaria del cielo a la tierra,\nél traerá nuevamente la tierra al cielo.\nA fin de cumplir su misión\nse le pidió ofrecerlo todos en parejas,\nun ejemplar masculino y uno femenino:\nun carnero y una carnera,\nun chivo y una chiva,\nun gallo y una gallina,\ny así por el estilo.\nỌ̀rúnmìlà oyó el aviso y realizó el sacrificio.\nPor eso es que la tierra se convierte en fructífera\ny se multiplica enormemente."}]$q$::jsonb,$q$[{"ref": "49.1", "yoruba": "Kosi abiyamo ti ko le bi awo lọmọ\nKosi abiyamo ti ko le bi Ọ̀rúnmìlà\nBaba-ẹni biobabini nipipe,\nbopẹtiti a tun nbi Baba-ẹni lomo,\nYeye-ẹni biobabini nipipe,\nbobapẹtiti a tun nbi yeye-ẹni l'ọmo:\na dífá f'Ọ̀rúnmìlà ti o wipe òun maa\nm'ọ̀run bọsayé òun maa mu\nayé l'osğrun.\nKiobaa leṣe bẹẹ dandan,\nWọ̀n niki ó rú\nOhun gbogbo ni méjiméji,\nako ati abo kan bayi:\nAgbo kan, àgutăn kan,\nòbúkọ kan, ewúrẹ kan,\nakuko-adiyẹ kan\nati agbebo-adiyẹ kan\nati bẹẹbẹẹ.\nÓ gbó ó rúbọ.\nBẹẹ ni ayé nbisii ti wọ̀n si nrẹ sii.", "medicina": "", "comentario": "", "traduccion": "\"No hay madre con hijos que no pueda haber parido\na un sacerdote de Ifá\"\n\"No hay madre con hijos, que no pueda haber parido a Ọ̀rúnmìlà\",\n\"Nuestro padre, si nos ha dado plena existencia,\ninevitablemente le daremos a él vida a cambio también\"\n\"Nuestra madre, si nos da plena existencia,\ninevitablemente le daremos a ella vida a cambio también.\nadivinaron Ifá para Ọ̀rúnmìlà,\ns* Significa que alguien puede dar vida, engendrar a quienes fueros sus ancestros.\nquien dijo que él bajaria del cielo a la tierra,\nél traerá nuevamente la tierra al cielo.\nA fin de cumplir su misión\nse le pidió ofrecerlo todos en parejas,\nun ejemplar masculino y uno femenino:\nun carnero y una carnera,\nun chivo y una chiva,\nun gallo y una gallina,\ny así por el estilo.\nỌ̀rúnmìlà oyó el aviso y realizó el sacrificio.\nPor eso es que la tierra se convierte en fructífera\ny se multiplica enormemente."}]$q$::jsonb),
('odu-050','oraculo-sagrado',$q$[{"ref": "50.1", "yoruba": "Bi ojumó ba nmọ̀ a\nkonly ògbẹ̀ri bi qjo-anọ:\nli o difá fún Kòmò,\nti o nronú bi oun\nti maaṣe kini yi si lana.\nÓ ronú titi ó sùn.\nNigbi Ojump mọ̀ ti yẹ̀ la,\nKòi mọ̀ eyiti oun maaṣe dandan.\nNjẹ ki a jẹki qjẹ bori ojẹ,\nbi ko ba to ki oṣu bori osu,\nbopẹtiti aó mọ̀ eyiti a maa ṣe.\nẸbọ: Akuko-adiyẹ mẹrin, ẹgbàárin owó ati ewé Ifá\nÓ gbọ̀ ó rú.\nWọ̀n ni:\n\"Ero rè a ma ṣe orí\".", "medicina": "poner cuatro uñas (garras) en agua fresca, para tomar como bebida.", "comentario": "", "traduccion": "Bi ojúmó ba nmọ a\nkoniy'ọ̀gbẹri bi ojo-anọ:\nadivinó Ifá para Kòmọ̀,\nquien estaba pensando en cómo hacer algo ayer.\nÉl meditó y luego durmió.\nAl día siguiente todavía no sabía qué hacer.\nPara resolver un problema debes calcular\ndía por día, y si es posible mes por mes\nhasta saber al final que debes de hacer.\nSacrificio: cuatro gallos, 8.000 cowries y medicina de Ifá.\nEl escuchó y realizó el sacrificio.\nEl adivino le aseguró:\n\"Las ideas (planes) vendrán solas a su cabeza\"."}, {"ref": "50.2", "yoruba": "Ifá I yoo ṣe abiyamo:\n\"Ngo ra osù ki'miri\nohun mu fi pa omọ lara\".\n\"Abiyamo kole ṣair'osù\nki o ler'ohun mupa omọ lara\":\na difá f'Ọ̀rúnmìlà,\nwọ̀n ni aya rè maa loyun o maa bimọ.\nEbọ: Agbebo-adiyẹ Méjì,\nosù ati egbejie-lógún owó.\nKiamu osù\nigi-osù fún un\nKi o tọju rẹ ni ireti la ti fi pa omo l'ara.\nIfá predijo que ella sería madre:\n\"Yo deseo comprar osù (polvo de madera roja)\npara frotar sobre mi hijo\"\n\"Una madre no puede ayudar a comprar osù\npara poder cuidar el cuerpo de su hijo\":", "medicina": "", "comentario": "", "traduccion": "adivinaron Ifá para Çrúnmilà,\nquien dijo que su esposa saldría preñada\ny que podría parir un hijo.\nSacrificio: dos gallinas,\npalo de madera roja de Angola\ny 4.400 cowries.\nDar el palo de osu a la mujer\npara que mantenga la esperanza\nde que ella lo usará\npara frotar el cuerpo de su hijo."}]$q$::jsonb,$q$[{"ref": "50.1", "yoruba": "Bi ojumó ba nmọ̀ a\nkonly ògbẹ̀ri bi qjo-anọ:\nli o difá fún Kòmò,\nti o nronú bi oun\nti maaṣe kini yi si lana.\nÓ ronú titi ó sùn.\nNigbi Ojump mọ̀ ti yẹ̀ la,\nKòi mọ̀ eyiti oun maaṣe dandan.\nNjẹ ki a jẹki qjẹ bori ojẹ,\nbi ko ba to ki oṣu bori osu,\nbopẹtiti aó mọ̀ eyiti a maa ṣe.\nẸbọ: Akuko-adiyẹ mẹrin, ẹgbàárin owó ati ewé Ifá\nÓ gbọ̀ ó rú.\nWọ̀n ni:\n\"Ero rè a ma ṣe orí\".", "medicina": "poner cuatro uñas (garras) en agua fresca, para tomar como bebida.", "comentario": "", "traduccion": "Bi ojúmó ba nmọ a\nkoniy'ọ̀gbẹri bi ojo-anọ:\nadivinó Ifá para Kòmọ̀,\nquien estaba pensando en cómo hacer algo ayer.\nÉl meditó y luego durmió.\nAl día siguiente todavía no sabía qué hacer.\nPara resolver un problema debes calcular\ndía por día, y si es posible mes por mes\nhasta saber al final que debes de hacer.\nSacrificio: cuatro gallos, 8.000 cowries y medicina de Ifá.\nEl escuchó y realizó el sacrificio.\nEl adivino le aseguró:\n\"Las ideas (planes) vendrán solas a su cabeza\"."}, {"ref": "50.2", "yoruba": "Ifá I yoo ṣe abiyamo:\n\"Ngo ra osù ki'miri\nohun mu fi pa omọ lara\".\n\"Abiyamo kole ṣair'osù\nki o ler'ohun mupa omọ lara\":\na difá f'Ọ̀rúnmìlà,\nwọ̀n ni aya rè maa loyun o maa bimọ.\nEbọ: Agbebo-adiyẹ Méjì,\nosù ati egbejie-lógún owó.\nKiamu osù\nigi-osù fún un\nKi o tọju rẹ ni ireti la ti fi pa omo l'ara.", "medicina": "", "comentario": "", "traduccion": "Ifá predijo que ella sería madre:\n\"Yo deseo comprar osù (polvo de madera roja)\npara frotar sobre mi hijo\"\n\"Una madre no puede ayudar a comprar osù\npara poder cuidar el cuerpo de su hijo\":\nadivinaron Ifá para Çrúnmilà,\nquien dijo que su esposa saldría preñada\ny que podría parir un hijo.\nSacrificio: dos gallinas,\npalo de madera roja de Angola\ny 4.400 cowries.\nDar el palo de osu a la mujer\npara que mantenga la esperanza\nde que ella lo usará\npara frotar el cuerpo de su hijo."}]$q$::jsonb),
('odu-058','oraculo-sagrado',$q$[{"ref": "58.1", "yoruba": "Igi-woroką niitú iná ka,\nÈniyàn iwèrè niitú ilé ara rẹ̀ ka:\na difá fún Baba-Ejò ati àwọn qmọ rè\nWọ̀n ni:\n\"Àwọn ọmọ ejò koniile ni ajohun\nkiwọn ko ara wọn jọ\nkiwọn wa kọ'ya l'ọjọ ijà.\nBi Baba-Ejò ba pe kiwọn ni ajohun\nkiwọn wa rúbo\":\nİgbin mẹrindilógún, ẹyẹlé,\noògùn burúkú\nati ẹgbàájo owó.\nWọ̀n gbọ̀ wọn ko rú.\n\"La madera hueca dispersa al fuego\".\n\"Un loco (quien pierde el juicio)\nsepara su propio hogar\":", "medicina": "", "comentario": "", "traduccion": "adivinó Ifá para la serpiente padre y sus hijos.\nEl adivino dijo:\n\"todos los descendientes de la serpiente\nnunca llegarían a estar de acuerdo\nen unirse (juntarse) para evitar un ataque.\nSi la serpiente padre quiere unirlos,\ndebe ofrecer sacrificio\":\ndieciséis caracoles de babosa, paloma,\nmedicina mala (veneno de serpiente)\ny 16.000 cowries.\nEllos escucharon y rehusaron sacrificar."}]$q$::jsonb,$q$[{"ref": "58.1", "yoruba": "Igi-woroką niitú iná ka,\nÈniyàn iwèrè niitú ilé ara rẹ̀ ka:\na difá fún Baba-Ejò ati àwọn qmọ rè\nWọ̀n ni:\n\"Àwọn ọmọ ejò koniile ni ajohun\nkiwọn ko ara wọn jọ\nkiwọn wa kọ'ya l'ọjọ ijà.\nBi Baba-Ejò ba pe kiwọn ni ajohun\nkiwọn wa rúbo\":\nİgbin mẹrindilógún, ẹyẹlé,\noògùn burúkú\nati ẹgbàájo owó.\nWọ̀n gbọ̀ wọn ko rú.", "medicina": "", "comentario": "", "traduccion": "\"La madera hueca dispersa al fuego\".\n\"Un loco (quien pierde el juicio)\nsepara su propio hogar\":\nadivinó Ifá para la serpiente padre y sus hijos.\nEl adivino dijo:\n\"todos los descendientes de la serpiente\nnunca llegarían a estar de acuerdo\nen unirse (juntarse) para evitar un ataque.\nSi la serpiente padre quiere unirlos,\ndebe ofrecer sacrificio\":\ndieciséis caracoles de babosa, paloma,\nmedicina mala (veneno de serpiente)\ny 16.000 cowries.\nEllos escucharon y rehusaron sacrificar."}]$q$::jsonb),
('odu-060','oraculo-sagrado',$q$[{"ref": "60.1", "yoruba": "İṣẹ kiide kiomamu ire rẹ bọ̀'ni,\nTibitire-Ejiwapo:\na dífá f'Owókosi-èniyàn-kosunwọ̀n\nWọ̀n ni:\nOjú tiori iṣé kioma barajẹ.\nKiotoju oruko rere.\nAdùn niigbẹhin ewúro.\nWọ̀n niki ó wa rúbą\nki Isé di Ọrọ̀ fún un.\nẸbọ: Ẹyẹlè, ẹgbèrindilógún owó ati ewé Ifá.\n\"La tribulación (pena, aflicción, adversidad)\nno llega sin estar rodeada de cosas buenas\"\n\"El bien y el mal siempre están juntos\":", "medicina": "machacar hojas amargas (ewé ewúro) y hojas de Oluṣesaju juntas, mezclarlas con jabón para baños del cliente. O triturar las hojas en agua (hojas de ewúro y Oluṣesaju) y usarlo junto con jabón para darse baños el cliente.", "comentario": "ewúro: VERNONIA AMYGDALINA Delile, Compositae.\nOluṣesaju: Debe ser igual que la planta Ojúùsájú: PETIVERIA ALLIACEA L., Phytolacaceae.", "traduccion": "adivinaron Ifá para Owókosi-èniyàn-kosunwọ̀n.\nLos adivinos le aconsejaron:\n\"no debe abatirse (desanimarse, angustiarse)\npor sufrir el ataque de la pobreza\"\n\"Él debe mantener su buen nombre\".\n\"La dulzura generalmente viene detrás\ndel sabor de una hoja amarga (ewúro)\".\nLe fue aconsejado hacer sacrificio\npara que su adversidad (tribulación)\npudiera convertirse en prosperidad.\nSacrificio: palomas, 3.200 cowries y medicina de Ifá."}, {"ref": "60.2", "yoruba": "Obirin dára e w'àṣé,\nQná-ngbaṣe-abiyamo da?:\na daa f'Ojú-oje, Ọlorun-ẹwà.\nWọ̀n ni ẹbọ niki o wa ṣe\nkiobaa le ṣe abiyamo.\nEbọ: Agbebo-adiyẹ, ewúrẹ,\nẹgbàá méjila owó ati ewé Ifá.\nUna mujer hermosa que no está menstruando,\n¿cómo puede ser posible que dé a luz hijos?:", "medicina": "", "comentario": "", "traduccion": "adivinó Ifá para Ojú-oje, la diosa de la belleza.\nLe fue aconsejado ofrecer sacrificio\npara que se pudiera convertirse en madre.\nSacrificio: gallina, chiva,\n24.000 cowries y medicina de Ifá."}]$q$::jsonb,$q$[{"ref": "60.1", "yoruba": "İṣẹ kiide kiomamu ire rẹ bọ̀'ni,\nTibitire-Ejiwapo:\na dífá f'Owókosi-èniyàn-kosunwọ̀n\nWọ̀n ni:\nOjú tiori iṣé kioma barajẹ.\nKiotoju oruko rere.\nAdùn niigbẹhin ewúro.\nWọ̀n niki ó wa rúbą\nki Isé di Ọrọ̀ fún un.\nẸbọ: Ẹyẹlè, ẹgbèrindilógún owó ati ewé Ifá.", "medicina": "machacar hojas amargas (ewé ewúro) y hojas de Oluṣesaju juntas, mezclarlas con jabón para baños del cliente. O triturar las hojas en agua (hojas de ewúro y Oluṣesaju) y usarlo junto con jabón para darse baños el cliente.", "comentario": "ewúro: VERNONIA AMYGDALINA Delile, Compositae.\nOluṣesaju: Debe ser igual que la planta Ojúùsájú: PETIVERIA ALLIACEA L., Phytolacaceae.", "traduccion": "\"La tribulación (pena, aflicción, adversidad)\nno llega sin estar rodeada de cosas buenas\"\n\"El bien y el mal siempre están juntos\":\nadivinaron Ifá para Owókosi-èniyàn-kosunwọ̀n.\nLos adivinos le aconsejaron:\n\"no debe abatirse (desanimarse, angustiarse)\npor sufrir el ataque de la pobreza\"\n\"Él debe mantener su buen nombre\".\n\"La dulzura generalmente viene detrás\ndel sabor de una hoja amarga (ewúro)\".\nLe fue aconsejado hacer sacrificio\npara que su adversidad (tribulación)\npudiera convertirse en prosperidad.\nSacrificio: palomas, 3.200 cowries y medicina de Ifá."}, {"ref": "60.2", "yoruba": "Obirin dára e w'àṣé,\nQná-ngbaṣe-abiyamo da?:\na daa f'Ojú-oje, Ọlorun-ẹwà.\nWọ̀n ni ẹbọ niki o wa ṣe\nkiobaa le ṣe abiyamo.\nEbọ: Agbebo-adiyẹ, ewúrẹ,\nẹgbàá méjila owó ati ewé Ifá.", "medicina": "", "comentario": "", "traduccion": "Una mujer hermosa que no está menstruando,\n¿cómo puede ser posible que dé a luz hijos?:\nadivinó Ifá para Ojú-oje, la diosa de la belleza.\nLe fue aconsejado ofrecer sacrificio\npara que se pudiera convertirse en madre.\nSacrificio: gallina, chiva,\n24.000 cowries y medicina de Ifá."}]$q$::jsonb),
('odu-073','oraculo-sagrado',$q$[{"ref": "73.1", "yoruba": "Baba omọ niiṣe t'ọmo ni ire.\nlye omo niiṣe t'ọmọ ni ire.\nOgbo ati Ato d'owọ Edú,\na dífá f'Olúyẹmi.\nA niki o wa rúbọ\nnitori àrùn Ìdí.\nẸbọ: Ẹyẹlé, agbebo-adiyẹ,\nakuko-adiyẹ, ẹja-aro,\negbàásàn owó\nati ewé Ifá.\nUn padre desea un hijo sano,\nuna madre desea un niño sano,\nla longevidad y la vejez dependen de Edú:", "medicina": "", "comentario": "", "traduccion": "adivinaron Ifá para Olúyemi,\nle fue aconsejado sacrificar,\npara prevenir el sufrimiento\nde una enfermedad\nen la parte baja del cuerpo\n(vientre, intestinos, genitales y ano).\nSacrificio: paloma, gallina,\ngallo, pescado ahumado,\n18.000 cowries\ny medicina de Ifá.\nNota: Un niño con este Odù en el \"Esẹntaye\" o en Itẹfá, si es varón,\nno deberá casarse con una mujer sin el consentimiento de su padre o de\nsu madre, si es hembra no lo deberá hacer sin el consentimiento de sus\npadres.\nTabú: el cliente no debe comer nuez kola, ni carne de animales\ndomésticos o criados en la granja (campo), sin embargo puede usar\npescado o caracol babosa para cocinar su sopa."}, {"ref": "73.2", "yoruba": "Qkọ̀ re-i-ko iwa ilè jọ:\na dífá f'Alárá.\nWọ̀n niki o wa rúbo\nki àwọn ebi rẹ̀ le maa jo\nki wọn ma tuka.\nEbọ: Iṣu-owọ,\nejigbere-eyẹlé,\negbàájo owó.\nAlárá gbọ̀ ó rú.\nWọ̀n ni:\nTo, Abariwon!\n1 yoo maa ye p.\nO, Alárá. Yiyẹ niiyẹ Alárá.\nEl azadón es el único\nque cuida del bienestar de la tierra:", "medicina": "", "comentario": "", "traduccion": "adivinó Ifá para Alárá.\nÉl le aconsejó que sacrificara,\npara que su familia no se dispersara,\nsino que se uniera.\nSacrificio: un manojo de escoba\n(unión de muchas cerdas de escoba),\ndos pichones de palomas,\ndieciséis miles cauris.\nAlárá ejecutó el sacrificio.\nEl adivino aseguró:\n¡To Abariwon!\n\"él será feliz el resto de sus días\".\nAlárá se convirtió en muy exitoso (próspero)."}]$q$::jsonb,$q$[{"ref": "73.1", "yoruba": "Baba omọ niiṣe t'ọmo ni ire.\nlye omo niiṣe t'ọmọ ni ire.\nOgbo ati Ato d'owọ Edú,\na dífá f'Olúyẹmi.\nA niki o wa rúbọ\nnitori àrùn Ìdí.\nẸbọ: Ẹyẹlé, agbebo-adiyẹ,\nakuko-adiyẹ, ẹja-aro,\negbàásàn owó\nati ewé Ifá.", "medicina": "", "comentario": "", "traduccion": "Un padre desea un hijo sano,\nuna madre desea un niño sano,\nla longevidad y la vejez dependen de Edú:\nadivinaron Ifá para Olúyemi,\nle fue aconsejado sacrificar,\npara prevenir el sufrimiento\nde una enfermedad\nen la parte baja del cuerpo\n(vientre, intestinos, genitales y ano).\nSacrificio: paloma, gallina,\ngallo, pescado ahumado,\n18.000 cowries\ny medicina de Ifá.\nNota: Un niño con este Odù en el \"Esẹntaye\" o en Itẹfá, si es varón,\nno deberá casarse con una mujer sin el consentimiento de su padre o de\nsu madre, si es hembra no lo deberá hacer sin el consentimiento de sus\npadres.\nTabú: el cliente no debe comer nuez kola, ni carne de animales\ndomésticos o criados en la granja (campo), sin embargo puede usar\npescado o caracol babosa para cocinar su sopa."}, {"ref": "73.2", "yoruba": "Qkọ̀ re-i-ko iwa ilè jọ:\na dífá f'Alárá.\nWọ̀n niki o wa rúbo\nki àwọn ebi rẹ̀ le maa jo\nki wọn ma tuka.\nEbọ: Iṣu-owọ,\nejigbere-eyẹlé,\negbàájo owó.\nAlárá gbọ̀ ó rú.\nWọ̀n ni:\nTo, Abariwon!\n1 yoo maa ye p.\nO, Alárá. Yiyẹ niiyẹ Alárá.", "medicina": "", "comentario": "", "traduccion": "El azadón es el único\nque cuida del bienestar de la tierra:\nadivinó Ifá para Alárá.\nÉl le aconsejó que sacrificara,\npara que su familia no se dispersara,\nsino que se uniera.\nSacrificio: un manojo de escoba\n(unión de muchas cerdas de escoba),\ndos pichones de palomas,\ndieciséis miles cauris.\nAlárá ejecutó el sacrificio.\nEl adivino aseguró:\n¡To Abariwon!\n\"él será feliz el resto de sus días\".\nAlárá se convirtió en muy exitoso (próspero)."}]$q$::jsonb),
('odu-075','oraculo-sagrado',$q$[{"ref": "75.1", "yoruba": "Ojú liafi nṣo orí,\nohun ti nṣe Ọ̀ṣẹ́ ko to inkan:\na daa f'Orunlojo igi.\nA niki wọ̀n wa rúbọ\nkiwọn ma baa gba àlejò buburú\ntiyoo pa wọn:\nỌbẹ mẹrin, òrí, epo\nati egàásan owó.\nWọ̀n gbọ̀ wọn ko rú.\nOpẹ̀ rúbọ ṣùgbọ̀n ko rúbo pe.\nPèrègún nikan li ó rúbo pe,\nwọ̀n ṣe ewé Ifá fún wọn.\nNjẹ ó di to, Abariwon!\nAfomo (Ọ̀ṣẹ́) kiip'Ọ̀pẹ,\nAfomo kiimọ Pèrègún,\nAfomo tiko gboran biobamo Pèrègún\nojú Pèrègún ni yoo ṣe kú dandan.\n\"Los ojos protegen a la cabeza\",\n\"Una pequeña cosa puede hacer\ndaños (estragos) incalculables\":", "medicina": "", "comentario": "", "traduccion": "adivinaron Ifá para los 165 árboles.\nLes fue aconsejado sacrificar,\npara evitar recibir un extraño peligroso\nque podría causarles mucho daño (matarlos):\nCuatro cuchillos, òrí, epo\ny 18.000 cowries debían ser sacrificados.\nEllos escucharon el consejo\npero la mayoría rehusó sacrificar.\nỌ̀pè (palma) sacrificó la mitad de los materiales,\nPèrègún cumplió y atendió el consejo.\nA los que sacrificaron les fue entregada\nla medicina de Ifá.\nFue declarado: ¡To Abariwon!\n\"los parásitos nunca dañarán a Ope\",\n\"los parásitos nunca atacarán a Pérègún\".\n\"Los parásitos testarudos\nque intenten atacar a Pèrègún,\nel filo del Pèrègún los matará con certeza\""}, {"ref": "75.2", "yoruba": "Qṣéṣewọn,\nwọ̀n nwadi Ọ̀ṣẹ́.\nbiabarúbo tan lia-nri-di Aṣeni.\nA daa fún Baalẹ-ero,\nwọ̀n nibi-o-ba-rúbo-a-ridi Aṣeni,\nÔ ni: kini ebọ?\nWọ̀n niki ó rú:\nAdiyẹ mérin,\nẹgbàárin owó ati ewé Ifá.\nEllos sufrieron un desastre (daño),\ntodos investigan las causas del mal,\npero hasta que cada uno no sacrificó\nno pudo descubrir la razón\nde tener un enemigo desconocido (Aṣeni'\"?):", "medicina": "", "comentario": "", "traduccion": "adivinó Ifá para Baalẹ-ẹro\n(El patrón de los viajeros)\nquien fue aconsejado que sacrificara\npara descubrir un enemigo desconocido.\nCuatro gallinas,\n8.000 cowries y medicina de Ifá.\n112 Aṣeni: enemigo desconocido. Aquel que desvirtúa o impide que se logren los\npropósitos de otro."}]$q$::jsonb,$q$[{"ref": "75.1", "yoruba": "Ojú liafi nṣo orí,\nohun ti nṣe Ọ̀ṣẹ́ ko to inkan:\na daa f'Orunlojo igi.\nA niki wọ̀n wa rúbọ\nkiwọn ma baa gba àlejò buburú\ntiyoo pa wọn:\nỌbẹ mẹrin, òrí, epo\nati egàásan owó.\nWọ̀n gbọ̀ wọn ko rú.\nOpẹ̀ rúbọ ṣùgbọ̀n ko rúbo pe.\nPèrègún nikan li ó rúbo pe,\nwọ̀n ṣe ewé Ifá fún wọn.\nNjẹ ó di to, Abariwon!\nAfomo (Ọ̀ṣẹ́) kiip'Ọ̀pẹ,\nAfomo kiimọ Pèrègún,\nAfomo tiko gboran biobamo Pèrègún\nojú Pèrègún ni yoo ṣe kú dandan.", "medicina": "", "comentario": "", "traduccion": "\"Los ojos protegen a la cabeza\",\n\"Una pequeña cosa puede hacer\ndaños (estragos) incalculables\":\nadivinaron Ifá para los 165 árboles.\nLes fue aconsejado sacrificar,\npara evitar recibir un extraño peligroso\nque podría causarles mucho daño (matarlos):\nCuatro cuchillos, òrí, epo\ny 18.000 cowries debían ser sacrificados.\nEllos escucharon el consejo\npero la mayoría rehusó sacrificar.\nỌ̀pè (palma) sacrificó la mitad de los materiales,\nPèrègún cumplió y atendió el consejo.\nA los que sacrificaron les fue entregada\nla medicina de Ifá.\nFue declarado: ¡To Abariwon!\n\"los parásitos nunca dañarán a Ope\",\n\"los parásitos nunca atacarán a Pérègún\".\n\"Los parásitos testarudos\nque intenten atacar a Pèrègún,\nel filo del Pèrègún los matará con certeza\""}, {"ref": "75.2", "yoruba": "Qṣéṣewọn,\nwọ̀n nwadi Ọ̀ṣẹ́.\nbiabarúbo tan lia-nri-di Aṣeni.\nA daa fún Baalẹ-ero,\nwọ̀n nibi-o-ba-rúbo-a-ridi Aṣeni,\nÔ ni: kini ebọ?\nWọ̀n niki ó rú:\nAdiyẹ mérin,\nẹgbàárin owó ati ewé Ifá.", "medicina": "", "comentario": "", "traduccion": "Ellos sufrieron un desastre (daño),\ntodos investigan las causas del mal,\npero hasta que cada uno no sacrificó\nno pudo descubrir la razón\nde tener un enemigo desconocido (Aṣeni'\"?):\nadivinó Ifá para Baalẹ-ẹro\n(El patrón de los viajeros)\nquien fue aconsejado que sacrificara\npara descubrir un enemigo desconocido.\nCuatro gallinas,\n8.000 cowries y medicina de Ifá.\n112 Aṣeni: enemigo desconocido. Aquel que desvirtúa o impide que se logren los\npropósitos de otro."}]$q$::jsonb),
('odu-082','oraculo-sagrado',$q$[{"ref": "82.1", "yoruba": "Bufúnmi-ki-mibufún o,\nAyé a maa gun,\na daa fOrúnmilà\nnlọ s'Otu-Ifẹ,\no maa kowon ni iṣe ilé, iṣe oko.\nWọ̀n nì:\nỌ̀rúnmìlà a wifún wọn,\nwón a gbọ̀.\nSùgbọ̀n kio wa rúbo\nkiotoo maa lowi fún wọn\newé qgbọ̀, gèdẹ̀ àgbagbà ati ẹgbajo owó.\nỌ̀rúnmìlà rúbọ.\n\"Una vida de dar y recibir\nhará del mundo un lugar más placentero para vivir\":", "medicina": "", "comentario": "", "traduccion": "adivinó Ifá para Ọ̀rúnmìlà\ncuando estaba dirigiéndose a Otù-lfè,\npara enseñar a las personas\na ser buenos vecinos,\na las gentes de la ciudad y a los del campo.\nEl adivino dijo:\n\"Ọ̀rúnmìlà será un capacitado instructor,\nellos aceptarán sus enseñanzas\"\nPero antes de hacer su viaje,\nél debía sacrificar:\nmucha nuez de kola amarga,\nhojas de ọgbó[118]\n, plátanos'\ny 16.000 cowries.\nỌ̀rúnmìlà sacrificó.\n118 pgbọ̀: NERVILIA UMBROSA (Rchb. f.) Schlt., Orchidaceae, PARQUETINA\nNIGRESCENS (Afzel.) Bullock, Asclepiadaceae.\nplátano: MUSA SAPIENTUM var. paradisiaca, Musaceae."}, {"ref": "82.2", "yoruba": "Ọmọ ko Alajé,\nota nta wàrà,\na dífá f'Oyinbo\nA niki Oyinbo wa rúbo\na maa ta pupqju.\nEbọ: lyọ igbio,\nadiyẹ-funfun, eyẹlé funfun,\negbàáwa owó.\nOyinbo gbó ó rú.\nO di Alajé.", "medicina": "", "comentario": "", "traduccion": "Ọmọ ko Alajé,\nota nta wàra,\nadivinó Ifá para Oyinbo (hombre blanco).\nLe fue aconsejado a Oyinbo sacrificar,\npara habilitarlo a vender en abundancia.\nSacrificio: puñado de sal equivalente a 200 cowries,\ngallina blanca, paloma blanca\ny 20.000 cowries.\nOyinbo escuchó y sacrificó.\nÉl se hizo próspero."}]$q$::jsonb,$q$[{"ref": "82.1", "yoruba": "Bufúnmi-ki-mibufún o,\nAyé a maa gun,\na daa fOrúnmilà\nnlọ s'Otu-Ifẹ,\no maa kowon ni iṣe ilé, iṣe oko.\nWọ̀n nì:\nỌ̀rúnmìlà a wifún wọn,\nwón a gbọ̀.\nSùgbọ̀n kio wa rúbo\nkiotoo maa lowi fún wọn\newé qgbọ̀, gèdẹ̀ àgbagbà ati ẹgbajo owó.\nỌ̀rúnmìlà rúbọ.", "medicina": "", "comentario": "", "traduccion": "\"Una vida de dar y recibir\nhará del mundo un lugar más placentero para vivir\":\nadivinó Ifá para Ọ̀rúnmìlà\ncuando estaba dirigiéndose a Otù-lfè,\npara enseñar a las personas\na ser buenos vecinos,\na las gentes de la ciudad y a los del campo.\nEl adivino dijo:\n\"Ọ̀rúnmìlà será un capacitado instructor,\nellos aceptarán sus enseñanzas\"\nPero antes de hacer su viaje,\nél debía sacrificar:\nmucha nuez de kola amarga,\nhojas de ọgbó[118]\n, plátanos'\ny 16.000 cowries.\nỌ̀rúnmìlà sacrificó.\n118 pgbọ̀: NERVILIA UMBROSA (Rchb. f.) Schlt., Orchidaceae, PARQUETINA\nNIGRESCENS (Afzel.) Bullock, Asclepiadaceae.\nplátano: MUSA SAPIENTUM var. paradisiaca, Musaceae."}, {"ref": "82.2", "yoruba": "Ọmọ ko Alajé,\nota nta wàrà,\na dífá f'Oyinbo\nA niki Oyinbo wa rúbo\na maa ta pupqju.\nEbọ: lyọ igbio,\nadiyẹ-funfun, eyẹlé funfun,\negbàáwa owó.\nOyinbo gbó ó rú.\nO di Alajé.", "medicina": "", "comentario": "", "traduccion": "Ọmọ ko Alajé,\nota nta wàra,\nadivinó Ifá para Oyinbo (hombre blanco).\nLe fue aconsejado a Oyinbo sacrificar,\npara habilitarlo a vender en abundancia.\nSacrificio: puñado de sal equivalente a 200 cowries,\ngallina blanca, paloma blanca\ny 20.000 cowries.\nOyinbo escuchó y sacrificó.\nÉl se hizo próspero."}]$q$::jsonb),
('odu-084','oraculo-sagrado',$q$[{"ref": "84.1", "yoruba": "Ajá sian titifide ehin enu wọn,\nAgbo sian titifide jojẹ:\na difá f'awa Èniyàn ni'kà\nỌlọ̀run li o wipe ki àwọn omọ-aráyé\nmaa ṣebọ Ọ̀rúnmìlà\nli o pe Oògùn ni sisa.\nÓ ni bi àwọn omọ aráyé\nbaṣẹ'bọ tán,\nti wọn tu erutan,\nki wọn wipe ki Elégbárá\njowọ ba wọn gbe ebọ de\nodo Olódùmarè.\nỌlorun ko torọ ebọ\nbẹẹni ko beere eru,\neniti nwa ire niiṣebo.\nÒriṣà-nlá li o wipe\nki omo-aráyé mamaa ran Èṣú\nni iṣé ti o buru o\nnitori ajadẹhinbo.\nEyẹlé mẹrin, awẹnu, osùn\nati ẹgbàá mẹrindilógún owó li ẹbọ.\nWọ̀n rúbọ.\nLati ọjo naa li Ọ̀rúnmìlà ti kọ èniyàn\nli asa iwẹ qjọ mẹta,\nojọ márùn ati if'osùn p'ara.\nPara un perro es agradable\nlos dientes en su boca,\nPara un carnero es agradable\nsus cuernos:", "medicina": "", "comentario": "", "traduccion": "adivinaron Ifá para la gente malvada.\nỌlórun instruyó a las personas del mundo\na que hagan sacrificio.\nỌ̀rúnmìlà instruyó sobre el uso de medicina.\nÉl dijo que si la gente hacía sacrificios,\nellos deberían implorar a Elegbara\nque lleve los sacrificios a Olódùmarè.\nDios no hace obligatorios los sacrificios.\nCualquiera que desee triunfar\nhará sacrificio.\nOriṣà-ńlá instruyó a la gente\na que se abstuviera\nde enviar a Èṣú mensajes malos,\na causa de sus repercusiones.\nCuatro palomas, jabón negro, osùn (madera roja de Angola)\ny 3.200 cowries debían ser sacrificados.\nEllos realizaron el sacrificio.\nDesde entonces\nỌ̀rúnmìlà ha enseñado a las personas\nel hábito de tomar sus baños cada 4 días\ny el uso de osùn para frotarse el cuerpo."}, {"ref": "84.2", "yoruba": "Ekitipẹtẹ:\na dífá f'Odẹ-ayé\na bu f'Odẹ-orun,\nA niki wọ̀n rú:\nẸyẹlé mẹrin ati egbàárin owo\nki oko-odẹ ti wọn lọ le san wọn bọ.\nQdẹ-ayé ko rú,\nOdẹ-orun li o rú.", "medicina": "", "comentario": "Un día mientras cazaban, Odẹ-orun tropezó con cinco huevos debajo de algunas hojas. Él los recogió. Cuando llegó a un cruce de caminos, él llamó a su colega y dijo: \"Odẹ-ayé ven y toma lo que dejé '. Él después regresó a su refugio.\npara ti aquí™ Odẹ-ayé que no tuvo ninguna caza ese día, cuando llegó a la encrucijada y halló los dos huevos grandes, los recogió con alegría.\nInmediatamente después que regresó a su choza, cocinó los huevos y se los comió. Al siguiente día, Ode-orun fue a donde guardó sus huevos.\nPara su sorpresa, él encontró 20.000 cowries debajo de cada huevo. Él rápidamente empaquetó las tres porciones del dinero el primero, segundo y tercer día. Entonces él saludó a Odẹ-ayé y le preguntó: \"¿qué hiciste con los huevos del otro día?\", Qdẹ-ayé respondió: \"los cociné y me los comi\", \"¿qué tal?\", \"fue delicioso\". Entonces Ode-orun dijo: \"se acabó, tú estás muerto\", \"tú, Ode-ayé, nunca prosperarás\".\nHoy nosotros decimos \"Ọ̀rúnmìlà\", lo que significa: \"sólo Dios posee prosperidad\", es el único que puede dar a cualquiera según su voluntad.", "traduccion": "Ekitipẹtẹ:\nadivinó Ifá para Odẹ-ayé'\nadivinó también para Odẹ-örun'.\nLes fue aconsejado sacrificar:\ncuatro palomas y 8.000 cowries\npara que sus expediciones de cacería\nfueran exitosas.\nOdẹ-ayé rechazó sacrificar.\nQdẹ-orun hizo el sacrificio.\n120 Qde-ayé: El cazador de la tierra.\n121 Qde-orun: El cazador del cielo."}]$q$::jsonb,$q$[{"ref": "84.1", "yoruba": "Ajá sian titifide ehin enu wọn,\nAgbo sian titifide jojẹ:\na difá f'awa Èniyàn ni'kà\nỌlọ̀run li o wipe ki àwọn omọ-aráyé\nmaa ṣebọ Ọ̀rúnmìlà\nli o pe Oògùn ni sisa.\nÓ ni bi àwọn omọ aráyé\nbaṣẹ'bọ tán,\nti wọn tu erutan,\nki wọn wipe ki Elégbárá\njowọ ba wọn gbe ebọ de\nodo Olódùmarè.\nỌlorun ko torọ ebọ\nbẹẹni ko beere eru,\neniti nwa ire niiṣebo.\nÒriṣà-nlá li o wipe\nki omo-aráyé mamaa ran Èṣú\nni iṣé ti o buru o\nnitori ajadẹhinbo.\nEyẹlé mẹrin, awẹnu, osùn\nati ẹgbàá mẹrindilógún owó li ẹbọ.\nWọ̀n rúbọ.\nLati ọjo naa li Ọ̀rúnmìlà ti kọ èniyàn\nli asa iwẹ qjọ mẹta,\nojọ márùn ati if'osùn p'ara.", "medicina": "", "comentario": "", "traduccion": "Para un perro es agradable\nlos dientes en su boca,\nPara un carnero es agradable\nsus cuernos:\nadivinaron Ifá para la gente malvada.\nỌlórun instruyó a las personas del mundo\na que hagan sacrificio.\nỌ̀rúnmìlà instruyó sobre el uso de medicina.\nÉl dijo que si la gente hacía sacrificios,\nellos deberían implorar a Elegbara\nque lleve los sacrificios a Olódùmarè.\nDios no hace obligatorios los sacrificios.\nCualquiera que desee triunfar\nhará sacrificio.\nOriṣà-ńlá instruyó a la gente\na que se abstuviera\nde enviar a Èṣú mensajes malos,\na causa de sus repercusiones.\nCuatro palomas, jabón negro, osùn (madera roja de Angola)\ny 3.200 cowries debían ser sacrificados.\nEllos realizaron el sacrificio.\nDesde entonces\nỌ̀rúnmìlà ha enseñado a las personas\nel hábito de tomar sus baños cada 4 días\ny el uso de osùn para frotarse el cuerpo."}, {"ref": "84.2", "yoruba": "Ekitipẹtẹ:\na dífá f'Odẹ-ayé\na bu f'Odẹ-orun,\nA niki wọ̀n rú:\nẸyẹlé mẹrin ati egbàárin owo\nki oko-odẹ ti wọn lọ le san wọn bọ.\nQdẹ-ayé ko rú,\nOdẹ-orun li o rú.", "medicina": "", "comentario": "Un día mientras cazaban, Odẹ-orun tropezó con cinco huevos debajo de algunas hojas. Él los recogió. Cuando llegó a un cruce de caminos, él llamó a su colega y dijo: \"Odẹ-ayé ven y toma lo que dejé '. Él después regresó a su refugio.\npara ti aquí™ Odẹ-ayé que no tuvo ninguna caza ese día, cuando llegó a la encrucijada y halló los dos huevos grandes, los recogió con alegría.\nInmediatamente después que regresó a su choza, cocinó los huevos y se los comió. Al siguiente día, Ode-orun fue a donde guardó sus huevos.\nPara su sorpresa, él encontró 20.000 cowries debajo de cada huevo. Él rápidamente empaquetó las tres porciones del dinero el primero, segundo y tercer día. Entonces él saludó a Odẹ-ayé y le preguntó: \"¿qué hiciste con los huevos del otro día?\", Qdẹ-ayé respondió: \"los cociné y me los comi\", \"¿qué tal?\", \"fue delicioso\". Entonces Ode-orun dijo: \"se acabó, tú estás muerto\", \"tú, Ode-ayé, nunca prosperarás\".\nHoy nosotros decimos \"Ọ̀rúnmìlà\", lo que significa: \"sólo Dios posee prosperidad\", es el único que puede dar a cualquiera según su voluntad.", "traduccion": "Ekitipẹtẹ:\nadivinó Ifá para Odẹ-ayé'\nadivinó también para Odẹ-örun'.\nLes fue aconsejado sacrificar:\ncuatro palomas y 8.000 cowries\npara que sus expediciones de cacería\nfueran exitosas.\nOdẹ-ayé rechazó sacrificar.\nQdẹ-orun hizo el sacrificio.\n120 Qde-ayé: El cazador de la tierra.\n121 Qde-orun: El cazador del cielo."}]$q$::jsonb),
('odu-086','oraculo-sagrado',$q$[{"ref": "86.1", "yoruba": "Iro-agogo-agboka:\na dífá f'Ọ̀rúnmìlà.\nWọ̀n ni:\n\"nibi gbogbo ayiká ayé\nni wọ̀n maa gbọ orukọ re\nti wọ̀n si maa maa wa mọo\".\nWọ̀n niki ó rúbọ\nki ara le rọọ.\nẸbọ: Eja-aro, ẹyẹlé\nati ẹgbàáwa owó.\nÓ gbọ̀ ó rú.\n\"El sonido de una campana\nse escucha en el mundo entero\":", "medicina": "", "comentario": "", "traduccion": "adivinó Ifá para Ọ̀rúnmìlà.\nEl adivino predijo:\n\"su nombre será escuchado\na lo largo y ancho del mundo\ny todo el mundo se esforzará\npara conocerlo a él\".\nLe fue aconsejado hacer sacrificio\npara tener buena salud (paz mental).\nSacrificio: pescado ahumado, paloma\ny 20.000 cowries.\nEl escuchó el consejo y sacrificó."}, {"ref": "86.2", "yoruba": "Aroka-Agboka:\na difá f'Osù.\nA niki Osù wa rúbẹ\nkio maa baa dùbúlẹ àisàn.\nKio maa baa kú.\nEbọ: ọfà inu apo, àgùtàn\nati ẹgbàá mẹjilélógún owó.\nÓ gbọ̀ ó rú.\nWọ̀n ni:\n\"Qfà kiidùbúlẹ ninu apo\".", "medicina": "", "comentario": "", "traduccion": "Aroka-Agboka\nadivinó Ifá para Osù.\nle fue aconsejado a Osù sacrificar,\npara evitar la enfermedad que provoca sueño,\nla cual podría ocasionarle la muerte.\nSacrificio: flecha en su funda (bolso),\ncarnera y 44.000 cowries.\nÉl oyó y sacrificó.\nEl adivino dice:\n\"una flecha nunca duerme dentro de su vaina\"\n12* dùbúlẹ àisàn: enfermedad del sueño, de dormitar."}]$q$::jsonb,$q$[{"ref": "86.1", "yoruba": "Iro-agogo-agboka:\na dífá f'Ọ̀rúnmìlà.\nWọ̀n ni:\n\"nibi gbogbo ayiká ayé\nni wọ̀n maa gbọ orukọ re\nti wọ̀n si maa maa wa mọo\".\nWọ̀n niki ó rúbọ\nki ara le rọọ.\nẸbọ: Eja-aro, ẹyẹlé\nati ẹgbàáwa owó.\nÓ gbọ̀ ó rú.", "medicina": "", "comentario": "", "traduccion": "\"El sonido de una campana\nse escucha en el mundo entero\":\nadivinó Ifá para Ọ̀rúnmìlà.\nEl adivino predijo:\n\"su nombre será escuchado\na lo largo y ancho del mundo\ny todo el mundo se esforzará\npara conocerlo a él\".\nLe fue aconsejado hacer sacrificio\npara tener buena salud (paz mental).\nSacrificio: pescado ahumado, paloma\ny 20.000 cowries.\nEl escuchó el consejo y sacrificó."}, {"ref": "86.2", "yoruba": "Aroka-Agboka:\na difá f'Osù.\nA niki Osù wa rúbẹ\nkio maa baa dùbúlẹ àisàn.\nKio maa baa kú.\nEbọ: ọfà inu apo, àgùtàn\nati ẹgbàá mẹjilélógún owó.\nÓ gbọ̀ ó rú.\nWọ̀n ni:\n\"Qfà kiidùbúlẹ ninu apo\".", "medicina": "", "comentario": "", "traduccion": "Aroka-Agboka\nadivinó Ifá para Osù.\nle fue aconsejado a Osù sacrificar,\npara evitar la enfermedad que provoca sueño,\nla cual podría ocasionarle la muerte.\nSacrificio: flecha en su funda (bolso),\ncarnera y 44.000 cowries.\nÉl oyó y sacrificó.\nEl adivino dice:\n\"una flecha nunca duerme dentro de su vaina\"\n12* dùbúlẹ àisàn: enfermedad del sueño, de dormitar."}]$q$::jsonb),
('odu-088','oraculo-sagrado',$q$[{"ref": "88.1", "yoruba": "Ẹniburúkú-ni-ẹjoti-a-nyin-wọn:\na difá f'Olódumarè,\nwọ̀n niki ó rúbọ\nki ẹnti o maa ran niṣé yi\nma le kọ iṣẹ naa.\nKi ayé le maa gun.\nİjapá Méjì, ewé ogbọ̀\nati egbẹtalélógbòn owó.\nÓ gbọ̀ ó rú.\nWọ̀n bọ òrun rè.\nNigbati o rúbọ tán,\no wa ran Irosutúrá losi òde-ayé.\nÀwọn aráyé ni:\nİwà İrosutúrá ko sun wọn.\nOdùduà ni:\nIre ni ọ̀un fiṣe s'ayé.\nNitorinaa òun\nko jẹ fi ẹlomiran rọ'po rẹ.\nÓ ni:\nBi ẹgbẹ ba jọ bobapẹ wọn a tuka.\nBi qjà ba kun bobapẹ titi a tú.\nBiibatiri bi pmo-èniyàn\nba jọ titi tii wọ̀n ko ba le tuka\nlọ ilé won?\n\"La gente mala dice que hay un día\nen que nosotros los alabaremos\":", "medicina": "", "comentario": "", "traduccion": "adivinó Ifá para Olódùmarè,\nle fue aconsejado hacer sacrificio\npara asegurar que a la persona\nque Él intente enviar con un recado,\nno rechazara la misión\nde hacer al mundo un lugar pacífico.\nSacrificio: dos jicoteas, hojas de ọgból\ny 6.600 cowries.\nDespués de realizar el sacrificio,\nEl envió a Irosutúrá al mundo.\nTodo el mundo se quejó:\n\"el carácter de Irosù Túrá no era bueno\".\nOdùduà dijo que él había enviado a Irosutúrá\npara el bien de la humanidad,\npor tanto no lo sustituiría por nadie más.\nEl dijo:\n\"si un grupo de personas se reúne,\ndespués de un tiempo el grupo se dispersará\".\n¿Cómo podría verse esto,\nsi las personas reunidas por un largo tiempo,\nsean incapaces de dispersarse\npara ir a sus distintos hogares?\n12 pgbọ̀: NERVILIA UMBROSA (Rchb. f.) Schlt., Orchidaceae, PARQUETINA\nNIGRESCENS (Afzel.) Bullock, Asclepiadaceae."}]$q$::jsonb,$q$[{"ref": "88.1", "yoruba": "Ẹniburúkú-ni-ẹjoti-a-nyin-wọn:\na difá f'Olódumarè,\nwọ̀n niki ó rúbọ\nki ẹnti o maa ran niṣé yi\nma le kọ iṣẹ naa.\nKi ayé le maa gun.\nİjapá Méjì, ewé ogbọ̀\nati egbẹtalélógbòn owó.\nÓ gbọ̀ ó rú.\nWọ̀n bọ òrun rè.\nNigbati o rúbọ tán,\no wa ran Irosutúrá losi òde-ayé.\nÀwọn aráyé ni:\nİwà İrosutúrá ko sun wọn.\nOdùduà ni:\nIre ni ọ̀un fiṣe s'ayé.\nNitorinaa òun\nko jẹ fi ẹlomiran rọ'po rẹ.\nÓ ni:\nBi ẹgbẹ ba jọ bobapẹ wọn a tuka.\nBi qjà ba kun bobapẹ titi a tú.\nBiibatiri bi pmo-èniyàn\nba jọ titi tii wọ̀n ko ba le tuka\nlọ ilé won?", "medicina": "", "comentario": "", "traduccion": "\"La gente mala dice que hay un día\nen que nosotros los alabaremos\":\nadivinó Ifá para Olódùmarè,\nle fue aconsejado hacer sacrificio\npara asegurar que a la persona\nque Él intente enviar con un recado,\nno rechazara la misión\nde hacer al mundo un lugar pacífico.\nSacrificio: dos jicoteas, hojas de ọgból\ny 6.600 cowries.\nDespués de realizar el sacrificio,\nEl envió a Irosutúrá al mundo.\nTodo el mundo se quejó:\n\"el carácter de Irosù Túrá no era bueno\".\nOdùduà dijo que él había enviado a Irosutúrá\npara el bien de la humanidad,\npor tanto no lo sustituiría por nadie más.\nEl dijo:\n\"si un grupo de personas se reúne,\ndespués de un tiempo el grupo se dispersará\".\n¿Cómo podría verse esto,\nsi las personas reunidas por un largo tiempo,\nsean incapaces de dispersarse\npara ir a sus distintos hogares?\n12 pgbọ̀: NERVILIA UMBROSA (Rchb. f.) Schlt., Orchidaceae, PARQUETINA\nNIGRESCENS (Afzel.) Bullock, Asclepiadaceae."}]$q$::jsonb),
('odu-089','oraculo-sagrado',$q$[{"ref": "89.1", "yoruba": "Irosù-Atẹ̀:\na difá fún Ọ̀rúnmìlà.\nWọ̀n ni:\nỌ̀rúnmìlà a maa tẹ̀ wọn\nnibi gbogbo agbaka ayé.\nWọ̀n niki ó wa rúbọ:\nAdiyẹ, ewé tètè ati egberindilógún owó\nÓ gbọ̀ ó rú.", "medicina": "", "comentario": "", "traduccion": "Irosù-Atè:\nadivinó Ifá por Ọ̀rúnmìlà,\nEl adivino dijo:\n\"Ọ̀rúnmìlà iniciará a muchas personas\nen todas partes del mundo\"\nLe fue aconsejado hacer sacrificio:\nGallina, hojas de tètẹ̀\ny 3.200 cowries.\nÉl oyó e hizo el sacrificio."}, {"ref": "89.2", "yoruba": "Àikú-ẹ̀gbọ̀n-Iwà,\na dífá fún İrosù,\na bu fún Ìrẹtẹ̀.\nWọ̀n niki Ìrosù pelu Ìrẹtẹ̀ wa rúbọ\nki Ọ̀rúnmìlà le ba wọ̀n rẹ.\nKi wọn ma baa kú.\nEwúrẹ ati egbàáwa owó li ebọ.\nWọ̀n gbọ̀ wọ̀n rú\nWọ̀n ni:\nOrí lyẹ̀-Irosù ni\nỌ̀rúnmìlà yoo maa gbe.\nLa inmortalidad (larga vida) es la mayor\nde las virtudes del buen carácter:", "medicina": "", "comentario": "127 tẹ̀tẹ̀: AMARANTHUS HYBRIDUS L. subsp. incurvatus (Timeroy) Brenan, Amaranthaceae.", "traduccion": "adivinó Ifá para Irosù,\ntambién adivinó para Ìrẹtẹ̀:\nLes fue aconsejado a Irosù\njunto con Ìrẹtẹ̀ hacer sacrificio\npara que Ọ̀rúnmìlà los siguiera favoreciendo\ny así poder evitar la muerte.\nChiva y 20.000 cowries\ndebían ser sacrificados.\nEllos oyeron y sacrificaron.\nEl adivino decretó:\n\"Sobre el lyè-Iròsù (polvo sagrado),\nỌ̀rúnmìlà siempre viviria\"."}]$q$::jsonb,$q$[{"ref": "89.1", "yoruba": "Irosù-Atẹ̀:\na difá fún Ọ̀rúnmìlà.\nWọ̀n ni:\nỌ̀rúnmìlà a maa tẹ̀ wọn\nnibi gbogbo agbaka ayé.\nWọ̀n niki ó wa rúbọ:\nAdiyẹ, ewé tètè ati egberindilógún owó\nÓ gbọ̀ ó rú.", "medicina": "", "comentario": "", "traduccion": "Irosù-Atè:\nadivinó Ifá por Ọ̀rúnmìlà,\nEl adivino dijo:\n\"Ọ̀rúnmìlà iniciará a muchas personas\nen todas partes del mundo\"\nLe fue aconsejado hacer sacrificio:\nGallina, hojas de tètẹ̀\ny 3.200 cowries.\nÉl oyó e hizo el sacrificio."}, {"ref": "89.2", "yoruba": "Àikú-ẹ̀gbọ̀n-Iwà,\na dífá fún İrosù,\na bu fún Ìrẹtẹ̀.\nWọ̀n niki Ìrosù pelu Ìrẹtẹ̀ wa rúbọ\nki Ọ̀rúnmìlà le ba wọ̀n rẹ.\nKi wọn ma baa kú.\nEwúrẹ ati egbàáwa owó li ebọ.\nWọ̀n gbọ̀ wọ̀n rú\nWọ̀n ni:\nOrí lyẹ̀-Irosù ni\nỌ̀rúnmìlà yoo maa gbe.", "medicina": "", "comentario": "127 tẹ̀tẹ̀: AMARANTHUS HYBRIDUS L. subsp. incurvatus (Timeroy) Brenan, Amaranthaceae.", "traduccion": "La inmortalidad (larga vida) es la mayor\nde las virtudes del buen carácter:\nadivinó Ifá para Irosù,\ntambién adivinó para Ìrẹtẹ̀:\nLes fue aconsejado a Irosù\njunto con Ìrẹtẹ̀ hacer sacrificio\npara que Ọ̀rúnmìlà los siguiera favoreciendo\ny así poder evitar la muerte.\nChiva y 20.000 cowries\ndebían ser sacrificados.\nEllos oyeron y sacrificaron.\nEl adivino decretó:\n\"Sobre el lyè-Iròsù (polvo sagrado),\nỌ̀rúnmìlà siempre viviria\"."}]$q$::jsonb),
('odu-094','oraculo-sagrado',$q$[{"ref": "94.1", "yoruba": "Iṣu wọ̀n,\nepo wọ̀n,\nàgbàdo wọ̀n,\nohungbogbo ti enu njẹ li o wọ̀n:\na difá fún wọ̀n l'ode Ìwòrì.\nWọn ni:\n\"ohungbogbo ti wọ̀n\nfún wọ̀n l'ode Ìwòrì yi,\nki wọ̀n wa rúbọ\nki ppọ le de fun wọ̀n\"\nẸbọ: Igba okọ̀, igba àdá,\neku, eja ati egbàáwa owó.\nWọ̀n gbọ̀ wọ̀n rú.\nBabaláwo niki gbogbo okunrin\nko ọkọ̀ ati àdá kiwọn maa re oko\nlọ ṣiṣẹ ki opo le de.\nIṣẹ nüide ipónjú.\nLos ñames eran caros,\nel aceite de palma era caro,\nel maíz era caro\ny otros alimentos eran caros.", "medicina": "", "comentario": "", "traduccion": "adivinaron Ifá para el pueblo de Ìwòrì.\nLos adivinos dijeron:\n\"todos los alimentos son caros\npara todos en el pueblo de lwòri.\nSe les aconsejó ofrecer sacrificio\npara que los artículos alimenticios\nfueran baratos\"\nSacrificio: 200 azadones,\n200 alfanjes (machetes),\nratas, pescados\ny 20.000 cowries.\nEllos escucharon y realizaron el sacrificio.\nEl Babaláwo dijo:\n\"los hombres cojan los azadones y machetes,\nvayan a trabajar la granja\npara que los alimentos\npuedan estar baratos\".\n\"Solamente el trabajo duro\npuede disminuir la miseria\""}, {"ref": "94.2", "yoruba": "Wèrè-nṣe-ẹlẹyaka'de wọ̀n nrẹrin:\na daa f'Ojügbebikan,\na niki ó wa rúbo,\nki aya rẹ ma di wèrè,\nbiobati di wèrè ki o le sàn.\nẸbọ: Igbín mẹrin,\nẹgbàárin owó ati ewé-Ifá.", "medicina": "", "comentario": "", "traduccion": "Wèrè-nṣe-ẹlẹyaka'de wọ̀n nrẹrín\nadivinó Ifá para Ojugbebikan\nquien fue aconsejado sacrificar,\npara impedir que su esposa se enloqueciera\no si ya ella estaba loca,\nrecuperara su cordura.\nSacrificio: cuatro caracoles babosa,\n8000 cowries y medicina de Ifá."}]$q$::jsonb,$q$[{"ref": "94.1", "yoruba": "Iṣu wọ̀n,\nepo wọ̀n,\nàgbàdo wọ̀n,\nohungbogbo ti enu njẹ li o wọ̀n:\na difá fún wọ̀n l'ode Ìwòrì.\nWọn ni:\n\"ohungbogbo ti wọ̀n\nfún wọ̀n l'ode Ìwòrì yi,\nki wọ̀n wa rúbọ\nki ppọ le de fun wọ̀n\"\nẸbọ: Igba okọ̀, igba àdá,\neku, eja ati egbàáwa owó.\nWọ̀n gbọ̀ wọ̀n rú.\nBabaláwo niki gbogbo okunrin\nko ọkọ̀ ati àdá kiwọn maa re oko\nlọ ṣiṣẹ ki opo le de.\nIṣẹ nüide ipónjú.", "medicina": "", "comentario": "", "traduccion": "Los ñames eran caros,\nel aceite de palma era caro,\nel maíz era caro\ny otros alimentos eran caros.\nadivinaron Ifá para el pueblo de Ìwòrì.\nLos adivinos dijeron:\n\"todos los alimentos son caros\npara todos en el pueblo de lwòri.\nSe les aconsejó ofrecer sacrificio\npara que los artículos alimenticios\nfueran baratos\"\nSacrificio: 200 azadones,\n200 alfanjes (machetes),\nratas, pescados\ny 20.000 cowries.\nEllos escucharon y realizaron el sacrificio.\nEl Babaláwo dijo:\n\"los hombres cojan los azadones y machetes,\nvayan a trabajar la granja\npara que los alimentos\npuedan estar baratos\".\n\"Solamente el trabajo duro\npuede disminuir la miseria\""}, {"ref": "94.2", "yoruba": "Wèrè-nṣe-ẹlẹyaka'de wọ̀n nrẹrin:\na daa f'Ojügbebikan,\na niki ó wa rúbo,\nki aya rẹ ma di wèrè,\nbiobati di wèrè ki o le sàn.\nẸbọ: Igbín mẹrin,\nẹgbàárin owó ati ewé-Ifá.", "medicina": "", "comentario": "", "traduccion": "Wèrè-nṣe-ẹlẹyaka'de wọ̀n nrẹrín\nadivinó Ifá para Ojugbebikan\nquien fue aconsejado sacrificar,\npara impedir que su esposa se enloqueciera\no si ya ella estaba loca,\nrecuperara su cordura.\nSacrificio: cuatro caracoles babosa,\n8000 cowries y medicina de Ifá."}]$q$::jsonb),
('odu-004','oraculo-sagrado',$q$[{"ref": "4.1", "yoruba": "Atẹlẹwó-abinutelu\nli o difá fún Itẹrẹ\nWọ̀n ni:\n\"Ero ti'oni orí li oun mi a maa pa\"\nNitorinaa ki ó rú:\niṣó, òbúkọ méta\nati akuko-adiyẹ mẹta.\nItẹrẹ gbó ó rú.\nWọ̀n ṣe ewé Ifá fún un kio maa muu.", "medicina": "", "comentario": "Entre los materiales prescritos para el sacrificio están los clavos con cabeza, que significan que ltere podrá tener sueños que se convertirán en realidad o permitirle que lleguen cabeza ideas su realizables que puedan ser materializadas.", "traduccion": "Atelẹwó-abinutelu:\nadivinó Ifá para Itẹrẹ.\nEllos dijeron\n\"sus ideas siempre podrían materializarse\",\nPor eso debe realizar sacrificio:\nclavos\"\n, tres chivos\ny tres gallos.\nIterẹ obedeció e hizo el sacrificio.\nEllos prepararon medicina de Ifá\npara que él las bebiera."}, {"ref": "4.2", "yoruba": "Ọpa-aro abidijẹgẹlẹgẹ:\nlo difá fún'wọn lode lfẹ,\nwọ̀n ni bi ikú ti npa wọn nibẹ yi.\nKi wọ̀n rú:\newọn kan ati agbo kan.\nWọ̀n gbọ̀ wọ̀n rú.\nBabaláwo ni:\n\"Okanṣoṣo ẹwọn kiikẹ,\nbẹẹ ni ọwọ̀ ikú ko ka wọn mọ\".\n\" Iṣó: clavo de metal. El significado más ancestral de Iṣó es: uña, pesuña, garra.\nPara elaborar la medicina de este Odù valorar el uso de garras, que también\ntienen la función mágica de \"fijar\" o \"agarrar\".", "medicina": "", "comentario": "La muerte estaba matando a todos en llé-lfẹ. Ifá fue consultado. El Babaláwo aconsejó a los residentes que hicieran un sacrificio que incluyera el eslabón de una cadena que nunca se pudiera romper. así fue como las intempestivas manos de la muerte fueron detenidas (la muerte fuera de tiempo).", "traduccion": "Opa-aro abidijegelege:\nadivinó Ifá para las personas en lfè,\ncuando-todos gritaban que la muerte\nastaba matando a las personas allí.\nEllos deblan sacrificar:\nuna cadena y un carnero padre.\nEllos lo oyeron y sacrificaron.\nEl Babaláwo dijo:\nUn eslabón simple nunca se rompe,\npor eso las manos de la muerte\nno pueden tocarlos por más tiempo\"."}, {"ref": "4.3", "yoruba": "Odidi-afiditi:\nli o difá f'Odidimadẹ.\nWọ̀n ni ki ó rú:\nagbon olodu móji.\nlgbin méjl\nati pgbörindilógün owó\nÔ gbọ̀ ó rú.\nBabalâwo ni: Ifá wipe:\n\"Ọmọ rọ̀ ko nii sọrọ loju rẹ̀.\"", "medicina": "", "comentario": "Òdí Méjì adivinó para Odidimadẹ, pero el rehúso ofrecer el sacrificio. Por lo tanto, de acuerdo a Ifá, su hijo quedará mudo por toda la vida.", "traduccion": "Odidi-afiditi adivinó Ifá para Odidimadẹ.\nEl aconsejó que ofreciera un sacrificio:\ndos cocos grandes (agbon olodu),\ndos caracoles babosa\ny 3200 cowries.\nEl rehúso hacer el sacrificio.\nEl Babaláwo dijo: Ifá dice:\n\"su hijo nunca hablara en esta vida\"."}, {"ref": "4.4", "yoruba": "Emi eni-òdí,\nIwọ èni-òdí,\nẹ̀ni-òdí Méjì:\nli o dífá f'Òdi nigba otẹ.\nWọ̀n ni: \"Qwọ̀ Òdí a Kalu\"\nNitorinaa ki ó rú:\nQja Idimo Méjì\nÓ gbọ̀ ó rú.", "medicina": "", "comentario": "Durante las hostilidades políticas entre dos pueblos, era obligatorio para los habitantes construir una muralla alrededor del pueblo para que los resguardara de los ataques enemigos. Esto se aplica a una comunidad, persona o familia que necesita protegerse de la amenaza de cualquier tipo de cosa que ponga en peligro su integridad o estabilidad.", "traduccion": "Yo soy èni-òdí,\nTú eres ẹ̀ni-òdí,\nDos eni-òdí:\nadivinaron para Odí (la muralla)\ndurante las hostilidades políticas.\nEllos dijeron: \"la muralla protegerá la ciudad\".\nPor lo tanto este debe ofrendar:\ndos ropas para abrigar.\nÉl escuchó e hizo la ofrenda."}]$q$::jsonb,$q$[{"ref": "4.1", "yoruba": "Atẹlẹwó-abinutelu\nli o difá fún Itẹrẹ\nWọ̀n ni:\n\"Ero ti'oni orí li oun mi a maa pa\"\nNitorinaa ki ó rú:\niṣó, òbúkọ méta\nati akuko-adiyẹ mẹta.\nItẹrẹ gbó ó rú.\nWọ̀n ṣe ewé Ifá fún un kio maa muu.", "medicina": "", "comentario": "Entre los materiales prescritos para el sacrificio están los clavos con cabeza, que significan que ltere podrá tener sueños que se convertirán en realidad o permitirle que lleguen cabeza ideas su realizables que puedan ser materializadas.\n\nIṣó: clavo de metal. El significado más ancestral de Iṣó es: uña, pesuña, garra.\nPara elaborar la medicina de este Odù valorar el uso de garras, que también\ntienen la función mágica de \"fijar\" o \"agarrar\".", "traduccion": "Atelẹwó-abinutelu:\nadivinó Ifá para Itẹrẹ.\nEllos dijeron\n\"sus ideas siempre podrían materializarse\",\nPor eso debe realizar sacrificio:\nclavos\"\n, tres chivos\ny tres gallos.\nIterẹ obedeció e hizo el sacrificio.\nEllos prepararon medicina de Ifá\npara que él las bebiera."}, {"ref": "4.2", "yoruba": "Ọpa-aro abidijẹgẹlẹgẹ:\nlo difá fún'wọn lode lfẹ,\nwọ̀n ni bi ikú ti npa wọn nibẹ yi.\nKi wọ̀n rú:\newọn kan ati agbo kan.\nWọ̀n gbọ̀ wọ̀n rú.\nBabaláwo ni:\n\"Okanṣoṣo ẹwọn kiikẹ,\nbẹẹ ni ọwọ̀ ikú ko ka wọn mọ\".", "medicina": "", "comentario": "La muerte estaba matando a todos en llé-lfẹ. Ifá fue consultado. El Babaláwo aconsejó a los residentes que hicieran un sacrificio que incluyera el eslabón de una cadena que nunca se pudiera romper. así fue como las intempestivas manos de la muerte fueron detenidas (la muerte fuera de tiempo).", "traduccion": "Opa-aro abidijegelege:\nadivinó Ifá para las personas en lfè,\ncuando-todos gritaban que la muerte\nastaba matando a las personas allí.\nEllos deblan sacrificar:\nuna cadena y un carnero padre.\nEllos lo oyeron y sacrificaron.\nEl Babaláwo dijo:\nUn eslabón simple nunca se rompe,\npor eso las manos de la muerte\nno pueden tocarlos por más tiempo\"."}, {"ref": "4.3", "yoruba": "Odidi-afiditi:\nli o difá f'Odidimadẹ.\nWọ̀n ni ki ó rú:\nagbon olodu móji.\nlgbin méjl\nati pgbörindilógün owó\nÔ gbọ̀ ó rú.\nBabalâwo ni: Ifá wipe:\n\"Ọmọ rọ̀ ko nii sọrọ loju rẹ̀.\"", "medicina": "", "comentario": "Òdí Méjì adivinó para Odidimadẹ, pero el rehúso ofrecer el sacrificio. Por lo tanto, de acuerdo a Ifá, su hijo quedará mudo por toda la vida.", "traduccion": "Odidi-afiditi adivinó Ifá para Odidimadẹ.\nEl aconsejó que ofreciera un sacrificio:\ndos cocos grandes (agbon olodu),\ndos caracoles babosa\ny 3200 cowries.\nEl rehúso hacer el sacrificio.\nEl Babaláwo dijo: Ifá dice:\n\"su hijo nunca hablara en esta vida\"."}, {"ref": "4.4", "yoruba": "Emi eni-òdí,\nIwọ èni-òdí,\nẹ̀ni-òdí Méjì:\nli o dífá f'Òdi nigba otẹ.\nWọ̀n ni: \"Qwọ̀ Òdí a Kalu\"\nNitorinaa ki ó rú:\nQja Idimo Méjì\nÓ gbọ̀ ó rú.", "medicina": "", "comentario": "Durante las hostilidades políticas entre dos pueblos, era obligatorio para los habitantes construir una muralla alrededor del pueblo para que los resguardara de los ataques enemigos. Esto se aplica a una comunidad, persona o familia que necesita protegerse de la amenaza de cualquier tipo de cosa que ponga en peligro su integridad o estabilidad.", "traduccion": "Yo soy èni-òdí,\nTú eres ẹ̀ni-òdí,\nDos eni-òdí:\nadivinaron para Odí (la muralla)\ndurante las hostilidades políticas.\nEllos dijeron: \"la muralla protegerá la ciudad\".\nPor lo tanto este debe ofrendar:\ndos ropas para abrigar.\nÉl escuchó e hizo la ofrenda."}]$q$::jsonb))
update textos t set versos=c.despues, actualizado=now() from c where t.odu_id=c.odu_id and t.libro=c.libro and t.versos=c.antes returning t.odu_id;
